/**
 * Writes src/viewer-page.ts from src/viewer.html. Run by `npm run build` before tsc, and by hand
 * with `npm run gen:viewer`. A test (test/viewer-page.test.ts) fails when the two are out of step.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";

const HEADER = `/**
 * GENERATED from viewer.html by scripts/gen-viewer-page.mjs. Do not edit this file by hand:
 * change viewer.html and run \`npm run gen:viewer\` (\`npm run build\` does it too).
 *
 * The live viewer page: one self-contained HTML document (inline CSS and JavaScript, no external
 * references). The host serves it at GET /viewer and GET /, on the same origin as /stream and /ws;
 * it is a client of docs/VIEWER-PROTOCOL.md.
 */
`;

/** The text of src/viewer-page.ts for the text of viewer.html (line ends normalised to \n). */
export function generateViewerPage(html) {
  const text = html.replace(/\r\n/g, "\n");
  return `${HEADER}export const VIEWER_HTML: string = ${JSON.stringify(text)};\n`;
}

export const HTML_PATH = fileURLToPath(new URL("../src/viewer.html", import.meta.url));
export const TS_PATH = fileURLToPath(new URL("../src/viewer-page.ts", import.meta.url));

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const out = generateViewerPage(readFileSync(HTML_PATH, "utf8"));
  writeFileSync(TS_PATH, out, "utf8");
  console.log(`wrote ${TS_PATH}`);
}
